param(
    [string]$SourcePath="$PSScriptRoot\..\assets\concept\HOUND\FX\hound_fx_background_removed_source.png",
    [string]$OutputDirectory="$PSScriptRoot\..\assets\enemies\sector_07\hound\fx"
)
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing
$a=[Drawing.Bitmap].Assembly.Location;$r=Split-Path $a;$refs=@($a,(Join-Path $r 'System.Drawing.Primitives.dll'),(Join-Path $r 'System.Private.Windows.GdiPlus.dll'),(Join-Path $r 'System.Private.Windows.Core.dll'),(Join-Path $r 'System.Private.CoreLib.dll'),(Join-Path $r 'System.Runtime.dll'),(Join-Path $r 'System.Collections.dll'))
Add-Type -ReferencedAssemblies $refs -TypeDefinition @'
using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.IO;
public static class HoundFxBuilder{
 static bool Checker(Color c){int hi=Math.Max(c.R,Math.Max(c.G,c.B)),lo=Math.Min(c.R,Math.Min(c.G,c.B));return lo>=185&&hi-lo<=14;}
 static Bitmap Cut(Bitmap s,Rectangle q){var b=s.Clone(q,PixelFormat.Format32bppArgb);int w=b.Width,h=b.Height;var v=new bool[w*h];var z=new int[w*h];int p=0,n=0;for(int x=0;x<w;x++)foreach(int y in new[]{0,h-1}){int i=y*w+x;if(!v[i]&&Checker(b.GetPixel(x,y))){v[i]=true;z[n++]=i;}}for(int y=0;y<h;y++)foreach(int x in new[]{0,w-1}){int i=y*w+x;if(!v[i]&&Checker(b.GetPixel(x,y))){v[i]=true;z[n++]=i;}}int[] dx={1,-1,0,0},dy={0,0,1,-1};while(p<n){int i=z[p++],x=i%w,y=i/w;b.SetPixel(x,y,Color.Transparent);for(int d=0;d<4;d++){int xx=x+dx[d],yy=y+dy[d];if(xx<0||yy<0||xx>=w||yy>=h)continue;int j=yy*w+xx;if(!v[j]&&Checker(b.GetPixel(xx,yy))){v[j]=true;z[n++]=j;}}}return b;}
 static Rectangle Bounds(Bitmap b){int x0=b.Width,y0=b.Height,x1=-1,y1=-1;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>=64){x0=Math.Min(x0,x);x1=Math.Max(x1,x);y0=Math.Min(y0,y);y1=Math.Max(y1,y);}if(x1<0)throw new InvalidDataException("Empty FX frame");return Rectangle.FromLTRB(x0,y0,x1+1,y1+1);}
 public static void Build(string src,string dst,int count,int sx,int sy,int sw,int sh,int fw,int fh){using(var sheet=new Bitmap(src)){var f=new Bitmap[count];var b=new Rectangle[count];int maxW=1,maxH=1;for(int i=0;i<count;i++){int x0=sx+(int)Math.Floor((double)i*sw/count),x1=sx+(int)Math.Floor((double)(i+1)*sw/count);f[i]=Cut(sheet,new Rectangle(x0,sy,x1-x0,sh));b[i]=Bounds(f[i]);maxW=Math.Max(maxW,b[i].Width);maxH=Math.Max(maxH,b[i].Height);}double scale=Math.Min((fw-4.0)/maxW,(fh-4.0)/maxH);using(var atlas=new Bitmap(count*fw,fh,PixelFormat.Format32bppArgb))using(var g=Graphics.FromImage(atlas)){g.Clear(Color.Transparent);g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;for(int i=0;i<count;i++){var q=b[i];int tw=Math.Max(1,(int)Math.Round(q.Width*scale)),th=Math.Max(1,(int)Math.Round(q.Height*scale));g.DrawImage(f[i],new Rectangle(i*fw+(fw-tw)/2,fh-2-th,tw,th),q,GraphicsUnit.Pixel);f[i].Dispose();}g.Dispose();for(int y=0;y<atlas.Height;y++)for(int x=0;x<atlas.Width;x++){var c=atlas.GetPixel(x,y);atlas.SetPixel(x,y,c.A<96?Color.Transparent:Color.FromArgb(255,c.R,c.G,c.B));}Directory.CreateDirectory(Path.GetDirectoryName(dst));atlas.Save(dst,ImageFormat.Png);}}}
 public static void BuildRects(string src,string dst,int sy,int sh,int[] edges,int[] picks,int fw,int fh){using(var sheet=new Bitmap(src)){int count=picks.Length;var f=new Bitmap[count];var b=new Rectangle[count];int maxW=1,maxH=1;for(int i=0;i<count;i++){int k=picks[i];f[i]=Cut(sheet,new Rectangle(edges[k],sy,edges[k+1]-edges[k],sh));b[i]=Bounds(f[i]);maxW=Math.Max(maxW,b[i].Width);maxH=Math.Max(maxH,b[i].Height);}double scale=Math.Min((fw-4.0)/maxW,(fh-4.0)/maxH);using(var atlas=new Bitmap(count*fw,fh,PixelFormat.Format32bppArgb))using(var g=Graphics.FromImage(atlas)){g.Clear(Color.Transparent);g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;for(int i=0;i<count;i++){var q=b[i];int tw=Math.Max(1,(int)Math.Round(q.Width*scale)),th=Math.Max(1,(int)Math.Round(q.Height*scale));g.DrawImage(f[i],new Rectangle(i*fw+(fw-tw)/2,fh-2-th,tw,th),q,GraphicsUnit.Pixel);f[i].Dispose();}g.Dispose();for(int y=0;y<atlas.Height;y++)for(int x=0;x<atlas.Width;x++){var c=atlas.GetPixel(x,y);atlas.SetPixel(x,y,c.A<96?Color.Transparent:Color.FromArgb(255,c.R,c.G,c.B));}Directory.CreateDirectory(Path.GetDirectoryName(dst));atlas.Save(dst,ImageFormat.Png);}}}
}
'@
$specs=[ordered]@{
 charge_trail_fx=@(5,0,10,1536,115,160,96);claw_slash_fx=@(6,0,330,1536,145,160,96);
 energy_projectile=@(4,0,485,768,105,48,48);destroy_fx=@(8,0,780,1536,175,160,96)
}
$src=[IO.Path]::GetFullPath($SourcePath);$out=[IO.Path]::GetFullPath($OutputDirectory);foreach($e in $specs.GetEnumerator()){$v=$e.Value;$dst=Join-Path $out ($e.Key+'.png');[HoundFxBuilder]::Build($src,$dst,[int]$v[0],[int]$v[1],[int]$v[2],[int]$v[3],[int]$v[4],[int]$v[5],[int]$v[6]);Write-Output("BUILT hound/fx/{0}: {1}x{2}"-f$e.Key,([int]$v[0]*[int]$v[5]),[int]$v[6])}
[HoundFxBuilder]::BuildRects($src,(Join-Path $out 'pounce_impact_fx.png'),140,165,[int[]](0,195,410,665,1015,1320,1536),[int[]](0,1,2,4,5),160,96);Write-Output 'BUILT hound/fx/pounce_impact_fx: 800x96'
[HoundFxBuilder]::BuildRects($src,(Join-Path $out 'energy_burst_fx.png'),590,170,[int[]](0,75,180,370,620,840,1050,1280,1536),[int[]](0,1,2,3,4,5,6,7),192,96);Write-Output 'BUILT hound/fx/energy_burst_fx: 1536x96'
